#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/quick_access_toolbar/quick_access_toolbar_values/quick_access_toolbar_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// QuickAccessToolbar's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/quick_access_toolbar.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Where the toolbar sits (see QuickAccessToolbarPlacement). A change rebuilds the customize menu and emits placement_changed. A value outside the enumeration throws std::invalid_argument.
template <typename Declaring>
struct QuickAccessToolbarPlacementPropertyCapability {
    PropertyCell<QuickAccessToolbarPlacement, QuickAccessToolbarPlacementPropertyCapability<Declaring>> placement{QuickAccessToolbarPlacement::above_ribbon};

    static void assign(QuickAccessToolbarPlacementPropertyCapability& capability, QuickAccessToolbarPlacement incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.placement), incoming);
        if (!capability.placement.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.placement));
    }
};

// Every QuickAccessToolbar capability, in the order the declaring class takes them.
template <typename Declaring>
struct QuickAccessToolbarCapabilities : public QuickAccessToolbarPlacementPropertyCapability<Declaring> {};

} // namespace gui_forms
